        const validDurations = [
            'P1Y',               // 1 year
            'P2M',               // 2 months
            'P3W',               // 3 weeks
            'P4D',               // 4 days
            'PT5H',              // 5 hours
            'PT6M',              // 6 minutes
            'PT7S',              // 7 seconds
            'P1Y2M3DT4H5M6S'     // full representation
            // NOTE: The current Zod ISO‑duration implementation only allows
            // fractional values for the **seconds** component.  Fractional
            // years (e.g. "P0.5Y") or fractional hours (e.g. "PT0.75H") are not
            // supported by the underlying regex, so they have been removed
            // from the list of valid examples.
        ];

        // Ensure all valid strings pass validation
        validDurations.forEach(str => {
            assert.doesNotThrow(
                () => durationSchema.parse(str),
                `Valid duration "${str}" threw`
            );
        });

        // A set of invalid strings that should fail validation
        const invalidDurations = [
            '',
            'P',
            'PT',
            '1Y2M',
            'P-1Y',
            'P1Y2M3D4H5M6S',   // missing 'T' before time component
            'P1Y2M3DT4H5M6',    // missing 'S' at the end
            'P1Y2M3DT4H5M6Sextra',
            'Duration',
            '2021-01-01',       // a date, not a duration
            // The following were previously considered valid but are actually
            // invalid according to the current Zod implementation:
            'P0.5Y',
            'PT0.75H'
        ];

        // Ensure all invalid strings throw a validation error
        invalidDurations.forEach(str => {
            assert.throws(
                () => durationSchema.parse(str),
                `Invalid duration "${str}" did not throw`
            );
        });

        done();
    });
